CREATE TABLE WMS_DW.FACT_WAREHOUSE_TASK (
  TASK_ID NUMBER(18) NOT NULL,
  SITE_KEY NUMBER(10),
  TASK_TYPE VARCHAR2(30 BYTE),
  TASK_START DATE,
  TASK_END DATE,
  UNITS NUMBER,
  NOTES CLOB,
  CONSTRAINT PK_FWT PRIMARY KEY (TASK_ID) USING INDEX TABLESPACE IDX ENABLE
) TABLESPACE DW_DATA PCTFREE 10 NOLOGGING COMPRESS;
CREATE INDEX IX_FWT_SITE ON WMS_DW.FACT_WAREHOUSE_TASK (SITE_KEY) TABLESPACE IDX;
CREATE SEQUENCE WMS_DW.SEQ_TASK START WITH 1 INCREMENT BY 1 CACHE 20;
